'use strict';
(() => {
  const DATA = window.LVD_CONTENT;
  const main = document.getElementById('main');
  const state = {user:null, saved:new Map(), requests:[], lastRequest:null, draft:{}, pending:null, auth:null, feedback:new Set(), sequence:1, preferences:new Map()};
  let timer = null, toastTimer = null, viewSerial = 0;
  const paths = {
    arrow:'M4 12h16M14 6l6 6-6 6', search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
    home:'M3 10l9-7 9 7M5 9v12h14V9M9 21v-8h6v8', user:'M20 21v-3a8 8 0 0 0-16 0v3M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
    family:'M16 21v-3a6 6 0 0 0-12 0v3M13 6a3 3 0 1 1-6 0 3 3 0 0 1 6 0M17 3a3 3 0 0 1 0 6M20 21v-4a6 6 0 0 0-3-5',
    pen:'M14 5l5 5M4 20l4-1L21 6a2 2 0 0 0-4-4L4 15z',
    file:'M14 2H5v20h14V7zM14 2v6h5M8 12h8M8 16h8',
    briefcase:'M9 6V3h6v3M3 6h18v14H3zM3 11l9 3 9-3M10 11h4v5h-4z',
    wallet:'M3 5h18v15H3zM3 9h18M15 13h6M17 16h1',
    globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3c-5 5-5 13 0 18M12 3c5 5 5 13 0 18',
    shield:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6zM8 12l3 3 5-6',
    bulb:'M9 21h6M9 18h6M8 14a7 7 0 1 1 8 0l-1 3H9z',
    bookmark:'M5 3h14v19l-7-5-7 5z', check:'M5 12l4 4L19 6', close:'M6 6l12 12M18 6L6 18', menu:'M4 6h16M4 12h16M4 18h16',
    filter:'M4 6h16M7 12h10M10 18h4', chevron:'M6 9l6 6 6-6', link:'M10 13a5 5 0 0 0 7 0l4-4a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-4 4a5 5 0 0 0 7 7l2-2',
    mail:'M3 5h18v14H3zM3 6l9 7 9-7', clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v5l3 2', book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3zM12 6v16'
  };
  const icon = (name, cls='') => `<svg viewBox="0 0 24 24" aria-hidden="true" class="${cls}"><path d="${paths[name] || paths.file}"/></svg>`;
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const norm = value => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase().trim();
  const url = (path, params={}) => {const q = new URLSearchParams(Object.entries(params).filter(([,v]) => v !== '' && v != null)); return '#' + path + (q.size ? '?' + q : '');};
  const articleURL = a => url((a.type === 'qa' ? '/hoi-dap/' : a.type === 'news' ? '/tin/' : '/bai-viet/') + a.id);
  const labelType = type => ({qa:'Hỏi đáp',guide:'Cẩm nang',news:'Tin pháp luật'}[type] || 'Nội dung');
  const topicName = id => DATA.topics.find(t => t[0] === id)?.[1] || 'Chưa phân loại';
  const article = id => DATA.articles.find(a => a.id === id);
  const parseRoute = () => {
    const legacy = {WF01:'/',WF02:'/chu-de',WF03:'/chu-de/nha-dat',WF04:'/tim-kiem?q=uy+quyen',WF05:'/hoi-dap/uy-quyen-quan-ly-nha',WF06:'/hoi-dap',WF07:'/cam-nang',WF08:'/ve-chuyen-trang',WF09:'/gui-cau-hoi',WF10:'/da-tiep-nhan',WF11:'/dang-nhap',WF12:'/tai-khoan',WF13:'/tai-khoan/cau-hoi/DEMO-0001'};
    const raw = location.hash.slice(1) || '/';
    const value = legacy[raw] || raw;
    try {const parsed = new URL(value.startsWith('/') ? value : '/not-found', 'https://preview.invalid'); return {path:parsed.pathname.replace(/\/$/,'') || '/',q:parsed.searchParams};}
    catch {return {path:'/not-found',q:new URLSearchParams()};}
  };
  const go = (path,params={}) => {const next=url(path,params); if(location.hash===next) render(); else location.hash=next;};
  const savedSet = () => {if(!state.user) return new Set(); if(!state.saved.has(state.user.email)) state.saved.set(state.user.email,new Set()); return state.saved.get(state.user.email);};
  const mine = () => state.user ? state.requests.filter(r => r.owner === state.user.email) : [];
  const crumb = (title,parent) => `<div class="breadcrumb"><a href="#/">Trang chủ</a><span>/</span>${parent ? `<a href="${parent[1]}">${esc(parent[0])}</a><span>/</span>` : ''}<span>${esc(title)}</span></div>`;
  const heading = (title,description='',eyebrow='') => `<div class="page-heading">${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}<h1>${esc(title)}</h1>${description?`<p>${esc(description)}</p>`:''}</div>`;
  const meta = a => a.editorial ? window.LVD_EDITORIAL.tag(a) : `<div class="meta"><span>${labelType(a.type)}</span><span>${esc(a.country)}</span><span>Bài mẫu</span></div>`;
  const searchForm = (q='', id='search-page') => `<form class="search-form" data-search role="search"><label class="sr-only" for="${id}">Bạn đang cần tìm hiểu điều gì?</label>${icon('search')}<input id="${id}" name="q" type="search" maxlength="180" placeholder="Bạn đang cần tìm hiểu điều gì?" value="${esc(q)}" autocomplete="off"><button type="submit" class="button" aria-label="Tìm kiếm"><span class="search-label">Tìm kiếm</span>${icon('arrow')}</button></form>`;
  const suggestions = () => `<div class="suggestions"><span class="try-label">Thử tìm:</span>${['Ủy quyền','Thừa kế','Quốc tịch','Chuyển tiền'].map(q=>`<a class="pill" href="${url('/tim-kiem',{q})}">${q}</a>`).join('')}</div>`;
  const cta = () => `<section class="cta-band"><div><h2>Chưa tìm thấy điều bạn cần?</h2><p>Đặt câu hỏi về tình huống riêng. Không cần tạo tài khoản trước.</p></div><a class="button" href="#/gui-cau-hoi">Gửi câu hỏi ${icon('arrow')}</a></section>`;
  const situationCard = s => `<a class="situation-card" href="${url('/tra-cuu',{'tinh-huong':s[0]})}"><span class="tile-icon">${icon(s[3])}</span><div><strong>${s[1]}</strong><p>${s[2]}</p></div>${icon('arrow','arrow')}</a>`;
  const questionRow = a => `<a class="question-row" href="${articleURL(a)}"><div><strong>${esc(a.title)}</strong>${meta(a)}</div>${icon('arrow')}</a>`;
  const featureCard = a => `<a class="feature-card" href="${articleURL(a)}"><span class="tag">${labelType(a.type)} · Bài mẫu</span><h3>${esc(a.title)}</h3><p>${esc(a.summary)}</p><span class="text-link">${a.type==='news'?'Xem cấu trúc bản tin':'Khám phá cẩm nang'} ${icon('arrow')}</span></a>`;
  const empty = (title,description,action='<a class="button" href="#/tra-cuu">Tiếp tục tra cứu</a>') => `<div class="empty-state"><span class="tile-icon">${icon('search')}</span><h2>${esc(title)}</h2><p>${esc(description)}</p><div class="button-row center">${action}</div></div>`;
  const notice = () => `<div class="notice"><strong>Nội dung minh họa.</strong> Đây là bản duyệt bố cục, chưa có kết luận pháp lý, căn cứ hoặc người kiểm duyệt được xác nhận.</div>`;

  function homeView(){
    return `<section class="hero"><div class="container"><div class="eyebrow">Dành cho người Việt tại Đức</div><div class="hero-copy"><h1>Hiểu luật rõ hơn.<br><span>An tâm từ xa.</span></h1><div class="hero-intro"><p>Tra cứu pháp luật Việt Nam và những vấn đề liên quan Việt Nam – Đức, bắt đầu từ điều bạn đang cần.</p><p class="small">Tra cứu mở · Không cần đăng nhập</p></div></div>${searchForm()}${suggestions()}</div></section><div class="container"><section class="section"><div class="section-heading"><div><h2>Bạn đang cần giải quyết việc gì?</h2><p>Chọn một tình huống. Không cần biết tên chuyên ngành luật.</p></div><a class="text-link" href="#/chu-de">Tất cả lĩnh vực ${icon('arrow')}</a></div><div class="situation-grid">${DATA.situations.map(situationCard).join('')}</div></section><section class="home-lower"><div><div class="section-heading"><h2>Câu hỏi để bắt đầu</h2><a class="text-link" href="#/hoi-dap">Xem tất cả ${icon('arrow')}</a></div><div class="question-list flat">${DATA.articles.slice(0,3).map(questionRow).join('')}</div></div><div><div class="section-heading"><h2>Góc cẩm nang</h2><a class="text-link" href="#/cam-nang">Khám phá ${icon('arrow')}</a></div>${featureCard(article('cam-nang-uy-quyen'))}</div></section>${cta()}</div>`;
  }
  const selectOptions = (values,current) => values.map(([value,label])=>`<option value="${esc(value)}"${value===current?' selected':''}>${esc(label)}</option>`).join('');
  function browseView(route){
    const q=route.q, keyword=q.get('q')||'', situation=q.get('tinh-huong')||'', topic=route.path.startsWith('/chu-de/')?route.path.split('/')[2]:(q.get('linh-vuc')||'');
    const kind=route.path==='/hoi-dap'?'qa':q.get('loai')||'', country=q.get('quoc-gia')||'', tab=route.path==='/chu-de'?'fields':q.get('xem')||'situations';
    const isSearch=route.path==='/tim-kiem'||!!keyword, s=DATA.situations.find(x=>x[0]===situation);
    const title=isSearch?'Kết quả tìm kiếm':s?s[1]:topic?topicName(topic):route.path==='/hoi-dap'?'Ngân hàng hỏi đáp':tab==='fields'?'Tra cứu theo lĩnh vực':'Bắt đầu từ điều bạn cần';
    const tokens=norm(keyword).split(/[^a-z0-9]+/).filter(Boolean);
    const matches=DATA.articles.map(a=>{const hay=norm(a.title+' '+a.summary+' '+a.keywords+' '+topicName(a.topic)); return {a,match:tokens.every(t=>hay.split(/[^a-z0-9]+/).some(w=>w===t||(t.length>=3&&w.startsWith(t)))),score:tokens.reduce((n,t)=>n+(norm(a.title).includes(t)?3:1),0)};}).filter(x=>x.match&&(!topic||x.a.topic===topic)&&(!situation||x.a.situations.includes(situation))&&(!kind||x.a.type===kind)&&(!country||x.a.country===country));
    if(q.get('sap-xep')==='a-z') matches.sort((x,y)=>x.a.title.localeCompare(y.a.title,'vi')); else matches.sort((x,y)=>y.score-x.score);
    const size=6,total=matches.length,pages=Math.max(1,Math.ceil(total/size)),page=Math.min(pages,Math.max(1,parseInt(q.get('trang'),10)||1));
    const params={q:keyword,'tinh-huong':situation,'linh-vuc':topic,'loai':kind,'quoc-gia':country,'sap-xep':q.get('sap-xep')||''};
    const filterItems=[['q',keyword],['tinh-huong',s?.[1]],['linh-vuc',topic?topicName(topic):''],['loai',kind?labelType(kind):''],['quoc-gia',country]].filter(([,v])=>v);
    const showHub=['/tra-cuu','/chu-de'].includes(route.path)&&!keyword&&!situation&&!topic&&!country&&!kind;
    return `<div class="container page">${crumb(title)}${heading(title,isSearch?'Tìm trong tin tức, cẩm nang và hỏi đáp. Có thể nhập tiếng Việt có dấu hoặc không dấu.':'Tình huống, lĩnh vực và hỏi đáp cùng dẫn về một thư viện nội dung.')}${searchForm(keyword)}${showHub?`<nav class="tabs" aria-label="Cách tra cứu"><a class="${tab==='situations'?'active':''}" href="#/tra-cuu" ${tab==='situations'?'aria-current="page"':''}>Theo tình huống</a><a class="${tab==='fields'?'active':''}" href="#/chu-de" ${tab==='fields'?'aria-current="page"':''}>Theo lĩnh vực</a><a href="#/hoi-dap">Tất cả hỏi đáp</a></nav>${tab==='fields'?`<div class="domain-grid">${DATA.topics.map(t=>`<a class="situation-card" href="${url('/chu-de/'+t[0])}"><span class="tile-icon">${icon(t[2])}</span><div><strong>${t[1]}</strong><p>${DATA.articles.filter(a=>a.topic===t[0]).length} nội dung minh họa</p></div>${icon('arrow','arrow')}</a>`).join('')}</div>`:`<div class="situation-grid">${DATA.situations.map(situationCard).join('')}</div>`}`:''}<div class="browse-layout"><details class="filter-panel" id="filters" ${matchMedia('(min-width:681px)').matches?'open':''}><summary>Bộ lọc ${icon('filter')}</summary><form id="filter-form" class="filter-body"><input type="hidden" name="q" value="${esc(keyword)}"><input type="hidden" name="tinh-huong" value="${esc(situation)}"><div><label for="filter-topic">Lĩnh vực</label><select id="filter-topic" name="linh-vuc">${selectOptions([['','Tất cả lĩnh vực'],...DATA.topics.map(t=>[t[0],t[1]])],topic)}</select></div><div><label for="filter-country">Phạm vi pháp luật</label><select id="filter-country" name="quoc-gia">${selectOptions([['','Tất cả phạm vi'],['Việt Nam','Việt Nam'],['Đức','Đức'],['Việt Nam – Đức','Việt Nam – Đức']],country)}</select></div><div><label for="filter-type">Loại nội dung</label><select id="filter-type" name="loai">${selectOptions([['','Tất cả nội dung'],['qa','Hỏi đáp'],['guide','Cẩm nang'],['news','Tin pháp luật']],kind)}</select></div><div class="filter-actions"><button class="button" type="submit">Áp dụng bộ lọc</button><a class="clear" href="${url('/tim-kiem',{q:keyword})}">Bỏ các bộ lọc</a></div></form></details><div><div class="results-top" role="status"><span><strong>${total}</strong> nội dung${total?` · Trang ${page}/${pages}`:''}</span><label class="sr-only" for="sort-results">Sắp xếp kết quả</label><select id="sort-results" data-sort>${selectOptions([['relevance','Phù hợp nhất'],['a-z','Theo tiêu đề A–Z']],q.get('sap-xep')||'relevance')}</select></div>${filterItems.length?`<div class="active-filters">${filterItems.map(([key,value])=>`<a class="pill active" aria-label="Bỏ lọc ${esc(value)}" href="${url('/tim-kiem',{...params,[key]:''})}">${esc(value)} <span aria-hidden="true">×</span></a>`).join('')}</div>`:''}${total?`<div class="question-list">${matches.slice((page-1)*size,page*size).map(({a})=>`<article class="result-item">${a.editorial?`<img class="press-search-thumb" src="assets/photos/${a.photo}-600.webp" alt="Ảnh minh họa cho bài viết" width="110" height="82" loading="lazy">`:""}${meta(a)}<h2><a href="${articleURL(a)}">${esc(a.title)}</a></h2><p>${esc(a.summary)}</p><a class="text-link read-link" href="${articleURL(a)}">${a.editorial?'Đọc tóm tắt & nguồn':a.type==='qa'?'Xem câu trả lời mẫu':'Đọc nội dung mẫu'} ${icon('arrow')}</a></article>`).join('')}</div>${pages>1?`<nav class="pagination" aria-label="Phân trang">${Array.from({length:pages},(_,i)=>`<a href="${url('/tim-kiem',{...params,trang:i+1})}" aria-label="Trang ${i+1}" ${page===i+1?'aria-current="page"':''}>${i+1}</a>`).join('')}</nav>`:''}`:empty('Chưa có nội dung phù hợp','Thử từ khóa ngắn hơn, bỏ một vài bộ lọc hoặc mô tả điều bạn cần tìm hiểu.',`<a class="button secondary" href="#/tra-cuu">Khám phá chủ đề</a><a class="button" href="#/gui-cau-hoi">Gửi câu hỏi ${icon('arrow')}</a>`)}</div></div>${cta()}</div>`;
  }
  function articleView(a){
    if(!a) return notFound();
    if(a.editorial) return window.LVD_EDITORIAL.story(a,{saved:savedSet().has(a.id)});
    const isQA=a.type==='qa',saved=savedSet().has(a.id);
    const related=DATA.articles.filter(x=>x.id!==a.id&&(x.topic===a.topic||x.situations.some(s=>a.situations.includes(s)))).slice(0,3);
    return `<div class="container page">${crumb(labelType(a.type),['Tra cứu','#/tra-cuu'])}<header class="article-head">${meta(a)}<h1>${esc(a.title)}</h1><p>${esc(a.summary)}</p></header><div class="article-meta"><div class="meta"><span>${esc(topicName(a.topic))}</span><span>Chưa kiểm duyệt · Nội dung mẫu</span></div><div class="button-row"><button class="button secondary" data-save="${a.id}" aria-pressed="${saved}">${icon('bookmark')}${saved?'Đã lưu':'Lưu bài'}</button><button class="button quiet" data-copy>${icon('link')}Chia sẻ</button></div></div><div class="article-layout"><div class="article-body">${notice()}<section class="answer-box" id="answer"><h2>${isQA?'Trả lời nhanh':'Điểm chính của bài viết'}</h2><p>${isQA?'Phần này sẽ đưa ra kết luận ngắn, kèm những điều kiện quan trọng để người đọc biết câu trả lời có phù hợp với mình hay không.':'Phần này sẽ tóm tắt nội dung cần biết trước khi người đọc đi vào các bước hoặc thông tin chi tiết.'} Trong bản duyệt, chưa đưa ra kết luận pháp lý.</p></section><section class="article-section" id="scope"><h2>Phạm vi cần làm rõ</h2><p>Bài mẫu được tổ chức cho nhu cầu <strong>${esc(a.title.charAt(0).toLowerCase()+a.title.slice(1))}</strong> Phạm vi quốc gia đang gắn cho nội dung là <strong>${esc(a.country)}</strong>; đây là nhãn phân loại để thử giao diện, chưa thay thế kiểm tra chuyên môn.</p></section><section class="article-section" id="steps"><h2>${isQA?'Những thông tin sẽ được làm rõ':'Lộ trình đọc đề xuất'}</h2>${a.checks.length?`<ul class="clean-list">${a.checks.map(t=>`<li>${icon('check')}<span>${esc(t)}</span></li>`).join('')}</ul>`:'<p>Bản tin chính thức sẽ trình bày sự kiện, nội dung liên quan đến người đọc và liên kết đến nguồn gốc. Chưa có tin pháp luật mới trong bản minh họa này.</p>'}<p class="muted">Các mục trên minh họa cấu trúc nội dung, không phải danh mục hồ sơ bắt buộc hoặc hướng dẫn thực hiện thủ tục.</p></section><section class="article-section" id="exceptions"><h2>Khi cần làm rõ trường hợp riêng</h2><p>Người đọc có thể chuyển sang biểu mẫu riêng, thay vì đăng thông tin cá nhân dưới bài. Khi nhấn “Gửi câu hỏi từ bài này”, hệ thống thử sẽ giữ lại ngữ cảnh bài đang đọc.</p><a class="text-link" href="${url('/gui-cau-hoi',{bai:a.id})}">Gửi câu hỏi từ bài này ${icon('arrow')}</a></section><section class="article-section source-box" id="sources"><h2>Nguồn & kiểm duyệt</h2><dl><dt>Căn cứ pháp lý</dt><dd>Chưa gắn nguồn trong bản duyệt. Bản chính thức cần tên văn bản, điều khoản và liên kết nguồn phù hợp.</dd><dt>Người kiểm duyệt</dt><dd>Chờ xác nhận. Không sử dụng tên hoặc tư cách chuyên gia minh họa.</dd><dt>Ngày rà soát pháp lý</dt><dd>Chưa có — không hiển thị ngày cập nhật giao diện như ngày kiểm tra pháp luật.</dd></dl><a class="text-link" href="#/ve-chuyen-trang">Xem nguyên tắc nội dung ${icon('arrow')}</a></section><div class="feedback"><p>${state.feedback.has(a.id)?'Đã ghi nhận phản hồi trong phiên dùng thử.':'Cách trình bày này có dễ theo dõi không?'}</p><div class="button-row"><button class="button secondary small" data-feedback="${a.id}" ${state.feedback.has(a.id)?'disabled':''}>Có, dễ theo dõi</button><button class="button secondary small" data-feedback="${a.id}" ${state.feedback.has(a.id)?'disabled':''}>Cần rõ hơn</button></div></div>${related.length?`<section class="article-section"><h2>Tiếp tục tìm hiểu</h2><div class="question-list">${related.map(questionRow).join('')}</div></section>`:''}</div><aside class="article-aside"><details class="toc" ${matchMedia('(min-width:681px)').matches?'open':''}><summary>Trong bài viết này</summary><nav aria-label="Mục lục bài viết">${[['answer',isQA?'Trả lời nhanh':'Điểm chính'],['scope','Phạm vi cần làm rõ'],['steps','Thông tin liên quan'],['exceptions','Trường hợp riêng'],['sources','Nguồn & kiểm duyệt']].map(([id,t])=>`<a href="${articleURL(a)}" data-scroll="${id}">${t}</a>`).join('')}</nav></details><div class="aside-help"><h3>Vấn đề của bạn có khác?</h3><p>Gửi câu hỏi riêng, không cần đăng nhập trước.</p><a class="text-link" href="${url('/gui-cau-hoi',{bai:a.id})}">Gửi câu hỏi ${icon('arrow')}</a></div></aside></div></div>`;
  }
  function editorialView(route){
    const selected=route.q.get('loai')||'',country=route.q.get('quoc-gia')||'';
    const items=DATA.articles.filter(a=>a.type!=='qa'&&(!selected||a.type===selected)&&(!country||a.country===country));
    return `<div class="container page">${crumb('Cẩm nang & Tin')}${heading('Hiểu bối cảnh. Tìm hướng đi.','Cẩm nang theo nhu cầu và tin pháp luật được tách rõ, để bạn chọn đúng cách đọc.','Cẩm nang & Tin')}<nav class="tabs" aria-label="Loại nội dung">${[['','Tất cả'],['guide','Cẩm nang'],['news','Tin pháp luật']].map(([v,t])=>`<a href="${url('/cam-nang',{loai:v,'quoc-gia':country})}" class="${selected===v?'active':''}" ${selected===v?'aria-current="page"':''}>${t}</a>`).join('')}</nav><div class="suggestions">${[['','Tất cả phạm vi'],['Việt Nam','Việt Nam'],['Đức','Đức'],['Việt Nam – Đức','Việt Nam – Đức']].map(([v,t])=>`<a class="pill ${country===v?'active':''}" href="${url('/cam-nang',{loai:selected,'quoc-gia':v})}">${t}</a>`).join('')}</div><p class="inline-summary">${items.length} nội dung minh họa · Chưa phải tin tức hoặc hướng dẫn pháp luật đã duyệt.</p>${items.length?`<div class="editorial-grid">${items.map(featureCard).join('')}</div>`:empty('Chuyên mục này chưa có bài mẫu','Thử phạm vi khác hoặc xem tất cả cẩm nang.',`<a class="button" href="#/cam-nang">Xem tất cả</a>`)}${cta()}</div>`;
  }
  function aboutView(){return `<div class="container page">${crumb('Về chuyên trang')}${heading('Ở xa, vẫn có thể bắt đầu từ thông tin rõ ràng.','Luật Việt Đức hướng đến tin tức, đời sống và pháp luật cho cộng đồng người Việt tại Đức. Bản đang xem dùng để duyệt cách tổ chức và trải nghiệm.','Về Luật Việt Đức')}<div class="principles"><section class="principle"><span class="number">01 / DỄ TRA CỨU</span><h2>Bắt đầu từ việc bạn cần.</h2><p>Tìm kiếm, chọn một tình huống hoặc tra theo lĩnh vực. Không bắt buộc biết tên chuyên ngành luật.</p></section><section class="principle"><span class="number">02 / RÕ PHẠM VI</span><h2>Biết thông tin áp dụng ở đâu.</h2><p>Nội dung ưu tiên pháp luật Việt Nam và vấn đề liên quan Việt Nam – Đức. Nội dung về Đức cần nguồn và chuyên gia phù hợp.</p></section><section class="principle"><span class="number">03 / KẾT NỐI RIÊNG</span><h2>Không phải công khai câu chuyện.</h2><p>Tra cứu mở cho mọi người. Các trao đổi về trường hợp riêng được tách khỏi thư viện nội dung công khai.</p></section></div><div class="prose"><h2>Nguồn và trách nhiệm nội dung</h2><p>Thiết kế dành vị trí rõ ràng cho căn cứ, người kiểm duyệt và ngày rà soát pháp lý. Thông tin này chỉ được công bố sau khi được xác nhận, không dùng dấu “đã duyệt” như một yếu tố trang trí.</p><h2>Đơn vị quản trị & đội ngũ</h2><p>Đang chờ xác nhận pháp nhân, đầu mối nội dung, đội ngũ chuyên môn và các kênh liên hệ chính thức. Tin tức được tóm tắt từ các nguồn được dẫn ngay trong bài. Bản duyệt không gắn logo đối tác, tên luật sư hoặc thông tin năng lực chưa được xác thực.</p><h2>Cách biên tập đề xuất</h2><p>Biên soạn → kiểm duyệt chuyên môn → xuất bản → rà soát và cập nhật. Câu hỏi riêng không tự động trở thành bài công khai.</p><details class="faq-accordion"><summary>Có cần tài khoản để đọc bài không?</summary><p>Không. Tìm kiếm, đọc nội dung và gửi câu hỏi đầu tiên là các luồng không yêu cầu đăng nhập. Tài khoản dùng để lưu bài và theo dõi trao đổi.</p></details><details class="faq-accordion"><summary>Bản HTML này đã tiếp nhận câu hỏi thật chưa?</summary><p>Chưa. Các thao tác dùng dữ liệu mẫu trong bộ nhớ của trang. Không gửi email, không có xác thực thật và không lưu hồ sơ trên máy chủ.</p></details></div>${cta()}</div>`;}
  function field(name,label,type='text',value='',optional=false){return `<div class="field"><label for="${name}">${label}${optional?'':` <span class="required">*</span>`}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${optional?'':'required'} ${type==='email'?'maxlength="254"':'maxlength="120"'} aria-describedby="${name}-error" autocomplete="off"><div class="error" id="${name}-error"></div></div>`;}
  function contactView(route){
    const d=state.draft,context=article(route.q.get('bai')),purpose=route.q.get('muc-dich')||d.purpose||'question';
    return `<div class="container page">${crumb('Gửi câu hỏi')}${heading('Bạn cần làm rõ điều gì?','Gửi câu hỏi, đề nghị trao đổi hoặc góp ý nội dung. Không cần đăng nhập.','Một tình huống riêng · Một đường kết nối rõ ràng')}<div class="contact-layout"><form id="contact-form" class="form-card" novalidate autocomplete="off"><div class="notice"><strong>Đang ở bản bấm thử.</strong> Chỉ nhập thông tin giả. Không gửi dữ liệu đến máy chủ, không gửi email; dữ liệu mất khi tải lại trang.<br><button type="button" class="button quiet small" data-fill-demo>Điền thông tin mẫu ${icon('arrow')}</button></div>${context?`<div class="notice info small">Đang hỏi từ bài: <strong>${esc(context.title)}</strong></div><input type="hidden" name="context" value="${context.id}">`:''}<div class="field"><label for="purpose">Bạn muốn <span class="required">*</span></label><select id="purpose" name="purpose" required>${selectOptions([['question','Gửi câu hỏi'],['discussion','Đề nghị trao đổi'],['feedback','Góp ý nội dung']],purpose)}</select></div><div class="field"><label for="question">Nội dung <span class="required">*</span></label><textarea id="question" name="question" required maxlength="3000" placeholder="Mô tả ngắn tình huống và điều bạn muốn tìm hiểu…" aria-describedby="question-hint question-error">${esc(d.question||'')}</textarea><small id="question-hint">Không nhập số định danh, thông tin ngân hàng hoặc nội dung hồ sơ thật. Tối đa 3.000 ký tự.</small><div id="question-error" class="error"></div></div><div class="field" id="topic-field" ${purpose==='feedback'?'hidden':''}><label for="topic">Lĩnh vực <span class="required">*</span></label><select id="topic" name="topic" aria-describedby="topic-error">${selectOptions([['','Chọn lĩnh vực'],['unknown','Tôi chưa rõ lĩnh vực'],...DATA.topics.map(t=>[t[0],t[1]])],d.topic||context?.topic||'')}</select><div id="topic-error" class="error"></div></div><div class="field-row">${field('name','Họ tên','text',d.name||state.user?.name||'')}${field('email','Email nhận phản hồi','email',d.email||state.user?.email||'')}</div><details class="optional-fields"><summary>Thêm thông tin liên hệ · Không bắt buộc</summary><div class="field-row">${field('phone','Điện thoại','tel',d.phone||'',true)}${field('available','Thời gian thuận tiện (kèm múi giờ)','text',d.available||'',true)}</div><p class="small muted" style="margin-bottom:16px">Đây chỉ là thông tin đề xuất, chưa phải lịch hẹn đã xác nhận.</p></details><div class="checkbox-row"><input id="consent" name="consent" type="checkbox" ${d.consent?'checked':''} aria-describedby="consent-error"><div><label for="consent">Tôi đồng ý xử lý thông tin để tiếp nhận và phản hồi yêu cầu. Xem <a href="#/chinh-sach-thong-tin">chính sách thông tin</a>. <span class="required">*</span><br><span class="muted">Checkbox minh họa, không phải thu thập đồng ý thật.</span></label><div class="error" id="consent-error"></div></div></div><div id="form-error" class="notice" role="alert" hidden></div><div class="form-actions"><button type="submit" class="button">Mô phỏng gửi câu hỏi ${icon('arrow')}</button><small>* Thông tin cần có trong biểu mẫu</small></div></form><aside class="contact-aside"><h3>Điều gì diễn ra tiếp theo?</h3><ol class="steps"><li><span class="step-number">1</span><div><strong>Tiếp nhận yêu cầu</strong><p>Trong hệ thống thật, chỉ xác nhận khi đã lưu thành công.</p></div></li><li><span class="step-number">2</span><div><strong>Phân loại và phân công</strong><p>Người phụ trách xác định phạm vi và hướng xử lý.</p></div></li><li><span class="step-number">3</span><div><strong>Phản hồi riêng</strong><p>Có thể xác thực tài khoản để theo dõi trao đổi trong hệ thống thật.</p></div></li></ol><div class="notice">Chưa tiếp nhận tệp hồ sơ.<br>Chưa cam kết lịch hẹn hoặc thời gian phản hồi.</div></aside></div></div>`;
  }
  function successView(){const r=state.lastRequest; if(!r) return `<div class="container page">${crumb('Xác nhận')}${empty('Chưa có lần gửi thử trong phiên này','Màn hình xác nhận chỉ xuất hiện sau khi hoàn thành biểu mẫu mô phỏng.',`<a class="button" href="#/gui-cau-hoi">Thử gửi câu hỏi</a>`)}</div>`;return `<div class="container page">${crumb('Xác nhận mô phỏng')}<section class="success-panel"><span class="tile-icon">${icon('check')}</span><h1>Đã hoàn tất bước gửi thử.</h1><p>Đây là màn hình xác nhận mẫu, không phải xác nhận tiếp nhận hồ sơ thực tế.</p><div class="reference">${r.id}</div><div class="notice info">Không có email được gửi đến <strong>${esc(r.owner)}</strong>. Yêu cầu chỉ tồn tại trong bộ nhớ của trang và sẽ mất khi tải lại.</div><div class="button-row center"><button class="button" data-follow="${r.id}">Thử theo dõi câu hỏi ${icon('arrow')}</button><a class="button secondary" href="#/tra-cuu">Tiếp tục tra cứu</a></div><p class="small muted" style="margin-top:22px">Mã tham chiếu không phải mật khẩu. Hệ thống thật cần xác thực và kiểm tra quyền truy cập.</p></section></div>`;}
  function authView(){
    const auth=state.auth;
    if(state.user) return accountView(parseRoute());
    return `<div class="container page"><div class="auth-wrap"><a class="text-link" href="#/tra-cuu">← Tiếp tục tra cứu</a><h1>${auth?'Nhập mã xác thực mẫu':'Lưu điều cần nhớ. Theo dõi điều đang hỏi.'}</h1><p>${auth?`Mô phỏng đăng nhập với ${esc(auth.email)}. Không có email được gửi.`:'Không cần mật khẩu trong luồng thiết kế. Đọc bài và gửi câu hỏi đầu tiên vẫn không cần tài khoản.'}</p><div class="form-card"><div class="notice"><strong>Chỉ mô phỏng, không xác thực thật.</strong> ${auth?'Mã dùng thử là <strong>123456</strong>, có thời hạn 5 phút trong phiên này.':'Chỉ dùng email giả, ví dụ ban-doc@example.invalid. Dữ liệu mất khi tải lại trang.'}</div>${auth?`<form id="otp-form" novalidate><div class="field"><label for="otp">Mã 6 chữ số</label><input id="otp" name="otp" class="otp" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="off" aria-describedby="otp-error" placeholder="••••••"><div id="otp-error" class="error" role="alert"></div></div><button class="button full" type="submit">Xác thực mô phỏng ${icon('arrow')}</button></form><div class="auth-actions"><button data-change-email>Đổi email dùng thử</button><button data-resend id="resend-code" ${Date.now()<auth.resendAt?'disabled':''}>Gửi lại mã mẫu</button></div>`:`<form id="email-form" novalidate>${field('login-email','Email dùng thử','email',state.pending?.email||'')}<button class="button full" type="submit">Tiếp tục bằng email ${icon('arrow')}</button></form><button class="button quiet full" style="margin-top:12px" data-demo-login>Xem với tài khoản mẫu</button>`}</div><p class="small muted" style="margin-top:20px">Xác thực email trong sản phẩm thật không phải xác thực danh tính pháp lý.</p></div></div>`;
  }
  function accountView(route){
    if(!state.user) return authView();
    const tab=route.q.get('muc')||'cau-hoi',list=mine();
    let body='';
    if(tab==='da-luu'){const articles=DATA.articles.filter(a=>savedSet().has(a.id));body=articles.length?`<div class="question-list">${articles.map(a=>`<div class="question-row"><div><a href="${articleURL(a)}"><strong>${esc(a.title)}</strong></a>${meta(a)}</div><button class="icon-button" aria-label="Bỏ lưu ${esc(a.title)}" data-save="${a.id}">${icon('bookmark')}</button></div>`).join('')}</div>`:empty('Chưa có bài viết đã lưu','Nhấn “Lưu bài” khi đang đọc để trở lại nội dung đó trong phiên dùng thử.');}
    else if(tab==='tuy-chon'){body=`<div class="form-card prose"><h2>Tùy chọn tài khoản mẫu</h2><p class="muted">${esc(state.user.email)}</p><div class="notice info" style="margin-top:24px">Tùy chọn nhận bản tin tách biệt với việc gửi câu hỏi. Bản duyệt không đăng ký vào dịch vụ email nào.</div><div class="checkbox-row"><input id="newsletter-demo" type="checkbox" ${state.preferences.get(state.user.email)?'checked':''}><label for="newsletter-demo">Tôi muốn nhận bản tin pháp luật (lựa chọn mô phỏng).</label></div><button class="button secondary" data-reset-demo>Xóa dữ liệu dùng thử</button></div>`;}
    else{body=list.length?list.map(r=>`<a class="request-card" href="${url('/tai-khoan/cau-hoi/'+r.id)}"><div><div class="meta"><span>${r.id}</span><span>Yêu cầu mẫu</span></div><strong>${esc(r.title)}</strong><span class="status-badge ${r.status==='Cần bổ sung'?'waiting':''}">${r.status}</span></div>${icon('arrow')}</a>`).join(''):empty('Bạn chưa có câu hỏi trong phiên này','Câu hỏi chỉ hiển thị với email tương ứng trong mô phỏng. Không có dữ liệu hồ sơ thật.',`<a class="button" href="#/gui-cau-hoi">Thử gửi câu hỏi ${icon('arrow')}</a>`);}
    return `<div class="container page">${crumb('Tài khoản')}<div class="account-head"><div><h1>Không gian của bạn</h1><p>Lưu nội dung, xem câu hỏi và tiếp tục trao đổi.</p></div><button class="button secondary" data-logout>Thoát dùng thử</button></div><div class="notice info" style="margin-top:25px"><strong>Tài khoản mô phỏng.</strong> Không phải đăng nhập thật. Toàn bộ dữ liệu nằm trong bộ nhớ trang, không lưu trên máy chủ.</div><nav class="tabs" aria-label="Không gian cá nhân">${[['cau-hoi','Câu hỏi của tôi'],['da-luu','Bài đã lưu'],['tuy-chon','Tùy chọn']].map(([id,label])=>`<a href="${url('/tai-khoan',{muc:id})}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav>${body}</div>`;
  }
  function threadView(id){
    if(!state.user){state.pending={path:'/tai-khoan/cau-hoi/'+id};return authView();}
    const r=mine().find(x=>x.id===id);
    if(!r) return `<div class="container page">${crumb('Câu hỏi riêng')}${empty('Không tìm thấy câu hỏi trong phiên của bạn','Mã trên đường dẫn không cấp quyền xem câu hỏi. Bản mô phỏng không có yêu cầu này cho email đang dùng.',`<a class="button" href="#/tai-khoan">Về câu hỏi của tôi</a>`)}</div>`;
    return `<div class="container page">${crumb('Chi tiết câu hỏi',['Tài khoản','#/tai-khoan'])}${heading(r.title,'Trao đổi mẫu chỉ hiển thị trong phiên dùng thử tương ứng.')}<div class="thread-layout"><div><div class="notice info">Đây là bản mô phỏng trao đổi, không có luật sư hoặc nhân viên tiếp nhận thật. Không nhập dữ liệu cá nhân hoặc hồ sơ thực tế.</div>${r.messages.map(m=>`<article class="message ${m.staff?'staff':''}"><div class="meta"><strong>${m.staff?'Người phụ trách (mô phỏng)':'Bạn (mô phỏng)'}</strong><span>${m.staff?'Phản hồi mẫu':'Chỉ trong phiên này'}</span></div><p>${esc(m.text)}</p></article>`).join('')}<form id="reply-form" class="form-card" data-request="${r.id}" novalidate><div class="field"><label for="reply">Bổ sung thông tin dùng thử</label><textarea id="reply" name="reply" maxlength="2000" placeholder="Chỉ nhập nội dung giả để xem luồng trao đổi…" aria-describedby="reply-error"></textarea><div class="error" id="reply-error" role="alert"></div></div><button class="button" type="submit">Mô phỏng gửi bổ sung ${icon('arrow')}</button></form></div><aside class="thread-aside"><div class="source-box"><div class="meta">Mã tham chiếu mẫu</div><h3 style="margin:10px 0 18px">${r.id}</h3><span class="status-badge ${r.status==='Cần bổ sung'?'waiting':''}">${r.status}</span><p class="small muted" style="margin-top:17px">Lịch hẹn và thời gian phản hồi chưa được cam kết.</p><a class="text-link" href="#/tai-khoan">Về danh sách ${icon('arrow')}</a></div></aside></div></div>`;
  }
  function policyView(kind){const privacy=kind==='privacy';return `<div class="container page">${crumb(privacy?'Chính sách thông tin':'Điều khoản sử dụng')}${heading(privacy?'Chính sách thông tin':'Điều khoản sử dụng','Vị trí trình bày văn bản chính sách. Bản này chưa phải văn bản pháp lý đã được duyệt.')}<div class="prose"><div class="notice">Nội dung bên dưới là ghi chú cho bản thử giao diện, không thay thế chính sách của website chính thức.</div><h2>Bản mô phỏng đang hoạt động thế nào?</h2><p>Không gửi biểu mẫu hoặc email. Không gọi API xử lý hồ sơ, không có công cụ phân tích được tích hợp. Dữ liệu dùng thử chỉ nằm trong bộ nhớ của trang và bị xóa khi tải lại. Máy chủ lưu trữ trang có thể có nhật ký truy cập thông thường ngoài phạm vi của mã giao diện này.</p><h2>${privacy?'Thông tin phải được chốt trước khi mở form thật':'Thông tin phải được chốt trước khi vận hành'}</h2><p>${privacy?'Pháp nhân chịu trách nhiệm; mục đích và cơ sở xử lý; loại thông tin thu thập; thời hạn lưu; nhà cung cấp; đầu mối tiếp nhận quyền dữ liệu và các trường hợp chuyển dữ liệu.':'Đơn vị quản trị; phạm vi nội dung; điều kiện sử dụng; giới hạn của thông tin công khai; quy trình tiếp nhận yêu cầu; trách nhiệm các bên và đầu mối liên hệ.'}</p><h2>Nội dung pháp luật trong bản thử</h2><p>Các bản tin chọn lọc có liên kết nguồn. Phần hỏi đáp còn dùng nội dung mẫu. Website đang duyệt giao diện, chưa có người kiểm duyệt pháp lý được xác nhận và không tiếp nhận hồ sơ thật.</p><a class="text-link" href="#/ve-chuyen-trang">Về chuyên trang ${icon('arrow')}</a></div></div>`;}
  function reviewView(){
    const rows=[['WF01','Trang chủ','/', 'Tin nổi bật có ảnh; đời sống, cộng đồng và đường tra cứu ngắn.'],['WF02','Chủ đề & tình huống','/chu-de','10 lĩnh vực; đổi cách xem, không tạo kho mới.'],['WF03','Lĩnh vực / nhóm chủ đề','/chu-de/nha-dat','Cùng mẫu kết quả, giữ bộ lọc theo URL.'],['WF04','Kết quả tìm kiếm','/tim-kiem?q=uy+quyen','Có dấu/không dấu, lọc, phân trang, trạng thái trống.'],['WF05','Nội dung chi tiết','/hoi-dap/uy-quyen-quan-ly-nha','Trả lời nhanh trước; phạm vi, nguồn, hành động sau.'],['WF06','Ngân hàng hỏi đáp','/hoi-dap','Một bộ lọc chỉ lấy câu hỏi từ kho dùng chung.'],['WF07','Tin tức & Sống ở Đức','/tin-tuc','Ảnh đa kích thước, bộ lọc chuyên mục và nguồn gốc bài viết.'],['WF08','Về chuyên trang','/ve-chuyen-trang','Nguyên tắc nội dung; không giả lập năng lực.'],['WF09','Gửi câu hỏi','/gui-cau-hoi','Không yêu cầu đăng nhập; có lựa chọn chưa rõ lĩnh vực.'],['WF10','Xác nhận tiếp nhận','/da-tiep-nhan','Chỉ có mã mẫu sau khi gửi thử thành công.'],['WF11','Xác thực email','/dang-nhap','Mã giả 123456; trở về thao tác trước đăng nhập.'],['WF12','Không gian cá nhân','/tai-khoan','Câu hỏi, bài lưu và tùy chọn tách biệt.'],['WF13','Chi tiết câu hỏi riêng','/tai-khoan/cau-hoi/DEMO-0001','Mở bằng tài khoản mẫu; không tiếp nhận hồ sơ thật.']];
    return `<div class="container page">${crumb('Sơ đồ & ghi chú duyệt')}${heading('Tin tức để đọc. Tra cứu khi cần.','Bản duyệt UX 0.4 · Tin tức có ảnh là điểm vào chính; 13 luồng tra cứu và hỗ trợ vẫn được giữ.','Luật Việt Đức · Trình duyệt bố cục')}<div class="review-grid"><section class="review-card"><h2>01 / Tin & đời sống</h2><p>Trang chủ ưu tiên tin có ảnh, đời sống và cộng đồng. Menu: Tin tức, Sống ở Đức, Cộng đồng và Tra cứu pháp luật.</p><a class="text-link" href="#/tra-cuu">Xem thư viện ${icon('arrow')}</a></section><section class="review-card"><h2>02 / Trắng, xám, đen</h2><p>Giao diện và ảnh chỉ dùng sắc độ trung tính. Ảnh tải theo kích thước màn hình; chú thích phân biệt ảnh minh họa và tư liệu.</p><a class="text-link" href="#/hoi-dap/uy-quyen-quan-ly-nha">Xem bài mẫu ${icon('arrow')}</a></section><section class="review-card"><h2>03 / Kết nối riêng</h2><p>Gửi câu hỏi không cần tài khoản. Chỉ mô phỏng xác thực khi lưu bài hoặc theo dõi trao đổi.</p><a class="text-link" href="#/gui-cau-hoi">Thử biểu mẫu ${icon('arrow')}</a></section></div><section class="section"><h2>Ba hành trình để trình bày</h2><p class="inline-summary">Bấm từng điểm để xem giao diện, hoặc thử từ Trang chủ như người đọc thông thường.</p><div class="flow" style="margin-top:24px"><a href="#/">Trang chủ</a>→<a href="#/tim-kiem?q=uy+quyen">Tìm “ủy quyền”</a>→<a href="#/hoi-dap/uy-quyen-quan-ly-nha">Đọc câu trả lời</a></div><div class="flow" style="margin-top:16px"><a href="#/tra-cuu?tinh-huong=thua-ke">Tình huống thừa kế</a>→<a href="#/hoi-dap/nhan-thua-ke-tai-viet-nam">Nội dung liên quan</a>→<a href="#/gui-cau-hoi?bai=nhan-thua-ke-tai-viet-nam">Gửi câu hỏi riêng</a></div><div class="flow" style="margin-top:16px"><a href="#/gui-cau-hoi">Điền dữ liệu mẫu</a>→<span>Mô phỏng tiếp nhận</span>→<span>Xác thực mẫu</span>→<a href="#/tai-khoan">Theo dõi & bổ sung</a></div></section><h2>Đối chiếu 13 mẫu trang</h2><div class="table-wrap"><table class="review-table"><thead><tr><th>Mã</th><th>Màn hình bấm thử</th><th>Điểm duyệt</th></tr></thead><tbody>${rows.map(([id,label,path,note])=>`<tr><td>${id}</td><td><a href="#${path}">${label}</a></td><td>${note}</td></tr>`).join('')}</tbody></table></div><section class="section"><h2>Trạng thái nên thử thêm</h2><div class="button-row" style="margin-top:20px"><a class="button secondary" href="#/tim-kiem?q=xyzkhongcoketqua">Không có kết quả</a><a class="button secondary" href="#/hoi-dap/bai-khong-ton-tai">Bài không tồn tại</a><a class="button secondary" href="#/gui-cau-hoi?test=error">Gửi lỗi rồi thử lại</a><a class="button secondary" href="#/dang-nhap">Mã sai / hết hạn</a></div></section><div class="notice info"><strong>Phạm vi bản duyệt:</strong> màu sắc, chữ, khoảng cách và cách nhóm nội dung là đề xuất giao diện. Nguồn pháp lý, nội dung chính thức, người kiểm duyệt, pháp nhân và thời gian phản hồi vẫn chờ xác nhận. Tin chọn lọc có nguồn tách biệt với câu hỏi pháp luật mẫu. Không coi ngày đối chiếu nguồn là ngày xuất bản tin.</div><div class="prose"><h2>Sau khi duyệt bố cục</h2><p>Kết nối kho nội dung được kiểm duyệt, xây hệ thống tiếp nhận và phân quyền trên máy chủ. Không dùng mã đăng nhập mô phỏng hoặc dữ liệu trong trình duyệt như tính năng bảo mật của sản phẩm thật.</p></div></div>`;
  }
  function notFound(){return `<div class="container page not-found">${empty('Trang này chưa có trong bản duyệt','Nội dung có thể chưa được tạo, hoặc đường dẫn không còn phù hợp. Bạn có thể tiếp tục từ thư viện.',`<a class="button secondary" href="#/">Về Trang chủ</a><a class="button" href="#/tra-cuu">Tra cứu nội dung ${icon('arrow')}</a>`)}</div>`;}

  function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4200);}
  function closeDialogs(){document.querySelectorAll('dialog[open]').forEach(d=>d.close());document.querySelectorAll('[data-dialog]').forEach(b=>b.setAttribute('aria-expanded','false'));}
  function render(){
    viewSerial++; clearInterval(timer); closeDialogs(); const route=parseRoute(); let html;
    if(route.path==='/') html=window.LVD_EDITORIAL.home();
    else if(['/tin-tuc','/song-o-duc','/cong-dong'].includes(route.path)) html=window.LVD_EDITORIAL.listing(route);
    else if(route.path==='/nguon-anh') html=window.LVD_EDITORIAL.credits();
    else if(['/tra-cuu','/chu-de','/hoi-dap','/tim-kiem'].includes(route.path)||route.path.startsWith('/chu-de/')) html=browseView(route);
    else if(/^\/(hoi-dap|bai-viet|tin)\//.test(route.path)) html=articleView(article(route.path.split('/')[2]));
    else if(['/cam-nang','/goc-viet-kieu','/tin-phap-luat'].includes(route.path)) html=window.LVD_EDITORIAL.listing(route);
    else if(route.path==='/ve-chuyen-trang') html=aboutView();
    else if(['/gui-cau-hoi','/lien-he'].includes(route.path)) html=contactView(route);
    else if(['/da-tiep-nhan','/lien-he/da-tiep-nhan'].includes(route.path)) html=successView();
    else if(['/dang-nhap','/tai-khoan/dang-nhap'].includes(route.path)) html=authView();
    else if(route.path==='/tai-khoan') html=accountView(route);
    else if(route.path.startsWith('/tai-khoan/cau-hoi/')) html=threadView(route.path.split('/')[3]);
    else if(route.path==='/chinh-sach-thong-tin') html=policyView('privacy');
    else if(route.path==='/dieu-khoan') html=policyView('terms');
    else if(route.path==='/so-do') html=reviewView();
    else html=notFound();
    main.innerHTML=html;
    const h1=main.querySelector('h1'); document.title=(h1?h1.textContent:'Luật Việt Đức')+' | Luật Việt Đức · Bản duyệt';
    document.querySelectorAll('.desktop-nav a').forEach(a=>{const active=a.dataset.nav==='lookup'?/\/(tra-cuu|tim-kiem|chu-de|hoi-dap)/.test(route.path):a.dataset.nav==='news'?route.path==='/tin-tuc'||route.path.startsWith('/tin/'):a.dataset.nav==='life'?['/song-o-duc','/cam-nang','/goc-viet-kieu'].includes(route.path)||route.path.startsWith('/bai-viet/'):a.dataset.nav==='community'?route.path==='/cong-dong':false; if(active) a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
    main.focus({preventScroll:true});window.scrollTo(0,0);
    if(document.getElementById('resend-code')) {const update=()=>{const b=document.getElementById('resend-code');if(!b||!state.auth)return;const remaining=Math.ceil((state.auth.resendAt-Date.now())/1000);b.disabled=remaining>0;b.textContent=remaining>0?`Gửi lại sau ${remaining}s`:'Gửi lại mã mẫu';};update();timer=setInterval(update,1000);}
    document.getElementById('page-announcement').textContent=h1?h1.textContent:'Nội dung đã mở';
  }
  function setError(form,id,message){const input=form.querySelector('#'+id),error=form.querySelector('#'+id+'-error'); if(input)input.setAttribute('aria-invalid',message?'true':'false'); if(error)error.textContent=message;}
  function login(email,seed=false){state.user={email:email.toLowerCase(),name:'Người dùng thử'};state.auth=null;
    if(seed&&!state.requests.some(r=>r.id==='DEMO-0001')) state.requests.push({id:'DEMO-0001',owner:state.user.email,title:'Ủy quyền quản lý nhà tại Việt Nam',status:'Cần bổ sung',messages:[{staff:false,text:'Đây là câu hỏi giả để thử giao diện theo dõi và bổ sung thông tin.'},{staff:true,text:'Đây là phản hồi mẫu, không phải ý kiến luật sư. Bạn có thể thử nhập một đoạn văn giả ở phần bổ sung bên dưới.'}]});
    const pending=state.pending;state.pending=null;
    if(pending?.save) savedSet().add(pending.save);
    if(pending?.path) go(pending.path);else go('/tai-khoan');
    if(pending?.save) toast('Đã lưu bài trong phiên dùng thử và trở lại bài đang đọc.');
  }
  function startAuth(email){state.auth={email:email.toLowerCase(),expiresAt:Date.now()+300000,resendAt:Date.now()+60000,attempts:0};render();setTimeout(()=>document.getElementById('otp')?.focus(),0);}
  function captureDraft(form){const data=Object.fromEntries(new FormData(form));state.draft={...data,consent:form.elements.consent.checked};return state.draft;}
  document.addEventListener('input',e=>{const form=e.target.closest('#contact-form');if(form)captureDraft(form);});
  document.addEventListener('change',e=>{
    if(e.target.id==='purpose') {document.getElementById('topic-field').hidden=e.target.value==='feedback';captureDraft(e.target.form);}
    if(e.target.matches('[data-sort]')){const r=parseRoute();const p=Object.fromEntries(r.q);if(r.path.startsWith('/chu-de/'))p['linh-vuc']=r.path.split('/')[2];if(r.path==='/hoi-dap')p.loai='qa';p['sap-xep']=e.target.value;delete p.trang;go('/tim-kiem',p);}
    if(e.target.id==='newsletter-demo'&&state.user){state.preferences.set(state.user.email,e.target.checked);toast('Đã đổi lựa chọn trong phiên thử. Không đăng ký bản tin thật.');}
  });
  document.addEventListener('click',async e=>{
    const target=e.target.closest('button,a');if(!target)return;
    if(target.id==='skip-main'){e.preventDefault();main.focus({preventScroll:true});main.scrollIntoView({block:'start'});return;}
    if(target.hasAttribute('data-scroll')){e.preventDefault();const section=document.getElementById(target.dataset.scroll);section?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'});if(section){section.setAttribute('tabindex','-1');section.focus({preventScroll:true});}return;}
    if(target.hasAttribute('data-dialog')){const dialog=document.getElementById(target.dataset.dialog);dialog?.showModal();target.setAttribute('aria-expanded','true');return;}
    if(target.hasAttribute('data-close')){closeDialogs();return;}
    if(target.hasAttribute('data-save')){const a=article(target.dataset.save);if(!a)return;if(!state.user){state.pending={save:a.id,path:articleURL(a).slice(1)};go('/dang-nhap');return;}const set=savedSet();const removed=set.has(a.id);removed?set.delete(a.id):set.add(a.id);const oldY=window.scrollY;render();window.scrollTo(0,oldY);document.querySelector('[data-save="'+a.id+'"]')?.focus({preventScroll:true});toast(removed?'Đã bỏ lưu trong phiên dùng thử.':'Đã lưu bài trong phiên dùng thử.');return;}
    if(target.hasAttribute('data-copy')){try{if(!navigator.clipboard)throw Error('Clipboard unavailable');await navigator.clipboard.writeText(location.href);toast('Đã sao chép liên kết bài viết.');}catch{toast('Trình duyệt chưa cho phép sao chép. Anh có thể lấy liên kết trên thanh địa chỉ.');}return;}
    if(target.hasAttribute('data-feedback')){state.feedback.add(target.dataset.feedback);const area=target.closest('.feedback');area.querySelector('p').textContent='Đã ghi nhận phản hồi trong phiên dùng thử.';area.querySelectorAll('button').forEach(b=>b.disabled=true);toast('Cảm ơn. Phản hồi chỉ được ghi nhận trong phiên này.');return;}
    if(target.hasAttribute('data-fill-demo')){const form=document.getElementById('contact-form');form.elements.name.value='Người dùng thử';form.elements.email.value='ban-doc@example.invalid';form.elements.question.value='Tôi đang thử giao diện để tìm hiểu việc ủy quyền quản lý nhà tại Việt Nam. Đây là nội dung giả, không phải yêu cầu pháp lý thật.';form.elements.topic.value='nha-dat';captureDraft(form);toast('Đã điền dữ liệu mẫu. Anh đánh dấu đồng ý minh họa rồi gửi thử.');return;}
    if(target.hasAttribute('data-follow')){const r=state.requests.find(x=>x.id===target.dataset.follow);if(!r)return;if(state.user?.email===r.owner)go('/tai-khoan/cau-hoi/'+r.id);else{state.user=null;state.auth=null;state.pending={path:'/tai-khoan/cau-hoi/'+r.id,email:r.owner};go('/dang-nhap');}return;}
    if(target.hasAttribute('data-demo-login')){login(state.pending?.email||'ban-doc@example.invalid',true);return;}
    if(target.hasAttribute('data-change-email')){state.auth=null;render();return;}
    if(target.hasAttribute('data-resend')&&state.auth&&Date.now()>=state.auth.resendAt){startAuth(state.auth.email);toast('Đã tạo lại mã mẫu 123456. Không có email được gửi.');return;}
    if(target.hasAttribute('data-logout')){state.user=null;state.auth=null;state.pending=null;go('/');toast('Đã thoát tài khoản dùng thử.');return;}
    if(target.hasAttribute('data-reset-demo')){state.user=null;state.saved.clear();state.requests=[];state.lastRequest=null;state.draft={};state.pending=null;state.auth=null;state.feedback.clear();state.preferences.clear();state.sequence=1;go('/');toast('Đã xóa dữ liệu dùng thử khỏi bộ nhớ của trang.');return;}
  });
  document.addEventListener('submit',e=>{
    const form=e.target;if(!(form instanceof HTMLFormElement))return;
    if(form.matches('[data-search]')){e.preventDefault();const keyword=String(new FormData(form).get('q')||'').trim().slice(0,180);closeDialogs();go(keyword?'/tim-kiem':'/tra-cuu',keyword?{q:keyword}:{});return;}
    if(form.id==='filter-form'){e.preventDefault();go('/tim-kiem',Object.fromEntries(new FormData(form)));return;}
    if(form.id==='email-form'){e.preventDefault();const input=form.elements['login-email'];setError(form,'login-email','');if(!input.value.trim()||!input.validity.valid){setError(form,'login-email','Nhập một email dùng thử đúng định dạng.');input.focus();return;}startAuth(input.value.trim());return;}
    if(form.id==='otp-form'){e.preventDefault();const input=form.elements.otp,auth=state.auth;if(!auth)return;let message='';if(Date.now()>auth.expiresAt)message='Mã mẫu đã hết hạn. Hãy tạo lại mã khi nút gửi lại khả dụng.';else if(auth.attempts>=5)message='Đã thử sai 5 lần. Hãy tạo lại mã mẫu.';else if(input.value!=='123456'){auth.attempts++;message='Mã chưa đúng. Mã mô phỏng của bản duyệt là 123456.';}if(message){setError(form,'otp',message);input.focus();return;}login(auth.email);return;}
    if(form.id==='contact-form'){
      e.preventDefault();if(form.dataset.sending==='true')return;const d=captureDraft(form);let invalid=false;
      for(const id of ['question','topic','name','email','consent']) setError(form,id,'');
      const error=(id,text)=>{setError(form,id,text);invalid=true;};
      if(!d.question?.trim())error('question','Vui lòng mô tả điều bạn cần làm rõ.');
      if(d.purpose!=='feedback'&&!d.topic)error('topic','Chọn lĩnh vực hoặc “Tôi chưa rõ lĩnh vực”.');
      if(!d.name?.trim())error('name','Vui lòng nhập tên dùng thử.');
      if(!d.email?.trim()||!form.elements.email.validity.valid)error('email','Vui lòng nhập email dùng thử đúng định dạng.');
      if(!d.consent)error('consent','Đánh dấu lựa chọn đồng ý minh họa để thử bước tiếp theo.');
      if(invalid){form.querySelector('[aria-invalid=true]')?.focus();return;}
      const alert=document.getElementById('form-error');alert.hidden=true;
      if(parseRoute().q.get('test')==='error'&&!form.dataset.failedOnce){form.dataset.failedOnce='true';alert.hidden=false;alert.textContent='Mô phỏng lỗi gửi: chưa tạo mã xác nhận. Thông tin đã nhập vẫn còn, anh có thể nhấn gửi lại.';alert.tabIndex=-1;alert.focus();return;}
      form.dataset.sending='true';const button=form.querySelector('[type=submit]');button.disabled=true;button.textContent='Đang mô phỏng…';const serial=viewSerial;
      setTimeout(()=>{if(serial!==viewSerial)return;const id='DEMO-LVD-'+String(state.sequence++).padStart(4,'0');const r={id,owner:d.email.trim().toLowerCase(),title:d.question.trim().slice(0,100)+(d.question.trim().length>100?'…':''),status:'Đã tiếp nhận',messages:[{staff:false,text:d.question.trim()}]};state.requests.push(r);state.lastRequest=r;state.draft={};go('/da-tiep-nhan');},400);return;
    }
    if(form.id==='reply-form'){e.preventDefault();const r=mine().find(x=>x.id===form.dataset.request),input=form.elements.reply;if(!r)return;if(!input.value.trim()){setError(form,'reply','Nhập nội dung giả trước khi gửi bổ sung.');input.focus();return;}r.messages.push({staff:false,text:input.value.trim()});r.status='Đã tiếp nhận';render();toast('Đã thêm nội dung trong phiên dùng thử. Không có thông tin được gửi ra ngoài.');}
  });
  document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
  document.getElementById('search-dialog-body').innerHTML=searchForm('','dialog-search')+suggestions();
  document.querySelectorAll('dialog').forEach(dialog=>{
    dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
    dialog.addEventListener('close',()=>document.querySelectorAll(`[data-dialog="${dialog.id}"]`).forEach(b=>b.setAttribute('aria-expanded','false')));
    dialog.querySelectorAll('a[href^="#/"]').forEach(a=>a.addEventListener('click',()=>closeDialogs()));
  });
  window.addEventListener('hashchange',render);
  window.addEventListener('resize',()=>{const panel=document.getElementById('filters');if(panel&&innerWidth>680)panel.open=true;});
  render();
})();
